public class Loops {
    public static void main(String[] args) {
        // for loop
        System.out.println("for loop:");
        for (int i = 0; i < 5; i++) {
            System.out.print(i + " ");
        }
        System.out.println();

        // while loop
        System.out.println("while loop:");
        int j = 0;
        while (j < 5) {
            System.out.print(j + " ");
            j++;
        }
        System.out.println();

        // do-while loop (executes at least once)
        System.out.println("do-while loop:");
        int k = 0;
        do {
            System.out.print(k + " ");
            k++;
        } while (k < 5);
        System.out.println();

        // Enhanced for loop (for-each)
        System.out.println("for-each loop:");
        int[] numbers = {10, 20, 30, 40, 50};
        for (int num : numbers) {
            System.out.print(num + " ");
        }
        System.out.println();

        // break and continue
        System.out.println("break at 3:");
        for (int i = 0; i < 10; i++) {
            if (i == 3) break;
            System.out.print(i + " ");
        }
    }
}

